// Fading an LED with PWM (analogWrite)
// Remember: analogWrite only works on the ~ pins (3, 5, 6, 9, 10, 11)

const int ledPin = 9;      // LED with a 220 ohm resistor on pin 9
int brightness = 0;        // current brightness 0..255
int fadeStep = 5;          // how much we change each time

void setup() {
  pinMode(ledPin, OUTPUT);
}

void loop() {
  analogWrite(ledPin, brightness);

  brightness = brightness + fadeStep;

  // when we hit either end, turn around
  if (brightness <= 0 || brightness >= 255) {
    fadeStep = -fadeStep;
  }

  delay(30);   // small delay so the fade is visible
}

