// Knight Rider style LED chase using an array of pins
// Six LEDs on pins 2..7, each with its own resistor.

const int ledPins[] = {2, 3, 4, 5, 6, 7};
const int ledCount = 6;
const int chaseDelay = 80;

void setup() {
  // set every LED pin as an output
  for (int i = 0; i < ledCount; i++) {
    pinMode(ledPins[i], OUTPUT);
  }
}

void loop() {
  // sweep left to right
  for (int i = 0; i < ledCount; i++) {
    digitalWrite(ledPins[i], HIGH);
    delay(chaseDelay);
    digitalWrite(ledPins[i], LOW);
  }

  // sweep back right to left
  for (int i = ledCount - 1; i >= 0; i--) {
    digitalWrite(ledPins[i], HIGH);
    delay(chaseDelay);
    digitalWrite(ledPins[i], LOW);
  }
}

