// ESP32 RGB LED using the LEDC hardware PWM peripheral
// The ESP32 does not use analogWrite(), it uses ledcWrite() on a channel.

const int redPin = 25;
const int greenPin = 26;
const int bluePin = 27;

const int redChannel = 0;
const int greenChannel = 1;
const int blueChannel = 2;

const int pwmFreq = 5000;      // 5 kHz
const int pwmResolution = 8;   // 8 bit -> values 0..255

void setup() {
  // set up one PWM channel per colour, then attach it to a pin
  ledcSetup(redChannel, pwmFreq, pwmResolution);
  ledcSetup(greenChannel, pwmFreq, pwmResolution);
  ledcSetup(blueChannel, pwmFreq, pwmResolution);

  ledcAttachPin(redPin, redChannel);
  ledcAttachPin(greenPin, greenChannel);
  ledcAttachPin(bluePin, blueChannel);
}

void loop() {
  // fade red up while blue fades down
  for (int level = 0; level <= 255; level++) {
    ledcWrite(redChannel, level);
    ledcWrite(blueChannel, 255 - level);
    ledcWrite(greenChannel, 0);
    delay(10);
  }

  for (int level = 255; level >= 0; level--) {
    ledcWrite(redChannel, level);
    ledcWrite(blueChannel, 255 - level);
    delay(10);
  }
}

