// Driving a 12V analog RGB LED strip through three MOSFETs
// The Arduino only supplies the gate signal, the strip is powered from 12V.

const int GATE_R = 3;
const int GATE_G = 5;
const int GATE_B = 6;

const int stepDelay = 15;

void setup() {
  pinMode(GATE_R, OUTPUT);
  pinMode(GATE_G, OUTPUT);
  pinMode(GATE_B, OUTPUT);

  // start with the strip off
  analogWrite(GATE_R, 0);
  analogWrite(GATE_G, 0);
  analogWrite(GATE_B, 0);
}

void loop() {
  // warm white fade up
  for (int v = 0; v <= 255; v++) {
    analogWrite(GATE_R, v);
    analogWrite(GATE_G, v * 3 / 4);   // a little less green
    analogWrite(GATE_B, v / 2);       // even less blue = warmer
    delay(stepDelay);
  }

  delay(2000);

  // fade back down
  for (int v = 255; v >= 0; v--) {
    analogWrite(GATE_R, v);
    analogWrite(GATE_G, v * 3 / 4);
    analogWrite(GATE_B, v / 2);
    delay(stepDelay);
  }

  delay(1000);
}

