// Debouncing a push button with millis()
// Mechanical buttons "bounce" for a few milliseconds when pressed.

const int buttonPin = 2;
const int ledPin = 8;

int lastReading = HIGH;
int stableState = HIGH;
unsigned long lastChangeTime = 0;
const unsigned long debounceDelay = 50;   // ms

int pressCount = 0;

void setup() {
  pinMode(buttonPin, INPUT_PULLUP);
  pinMode(ledPin, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int reading = digitalRead(buttonPin);

  // the reading changed, restart the timer
  if (reading != lastReading) {
    lastChangeTime = millis();
  }

  // the reading has been steady long enough, accept it
  if (millis() - lastChangeTime > debounceDelay) {
    if (reading != stableState) {
      stableState = reading;

      if (stableState == LOW) {
        pressCount++;
        Serial.print("Press number: ");
        Serial.println(pressCount);
        digitalWrite(ledPin, HIGH);
      } else {
        digitalWrite(ledPin, LOW);
      }
    }
  }

  lastReading = reading;
}

