// Toggle switch behaviour: press once for on, press again for off.
// We only act on the moment the button goes from released to pressed.

const int BTN = 7;
const int LED = 12;

bool ledOn = false;
int previousButton = HIGH;

void setup() {
  pinMode(BTN, INPUT_PULLUP);
  pinMode(LED, OUTPUT);
}

void loop() {
  int buttonNow = digitalRead(BTN);

  // falling edge = the press just happened
  if (previousButton == HIGH && buttonNow == LOW) {
    ledOn = !ledOn;                  // flip the state
    digitalWrite(LED, ledOn ? HIGH : LOW);
    delay(50);                       // crude debounce
  }

  previousButton = buttonNow;
}

