// Short press blinks once, long press (over 1 second) keeps the LED on.

const int buttonPin = 3;
const int ledPin = 10;
const unsigned long longPressTime = 1000;

unsigned long pressStart = 0;
bool buttonWasDown = false;

void setup() {
  pinMode(buttonPin, INPUT_PULLUP);
  pinMode(ledPin, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  bool buttonDown = (digitalRead(buttonPin) == LOW);

  if (buttonDown && !buttonWasDown) {
    // the press has just started
    pressStart = millis();
    buttonWasDown = true;
  }

  if (!buttonDown && buttonWasDown) {
    // the button was just released, how long was it held?
    unsigned long heldFor = millis() - pressStart;
    buttonWasDown = false;

    if (heldFor >= longPressTime) {
      Serial.println("Long press");
      digitalWrite(ledPin, HIGH);
      delay(2000);
      digitalWrite(ledPin, LOW);
    } else {
      Serial.println("Short press");
      digitalWrite(ledPin, HIGH);
      delay(150);
      digitalWrite(ledPin, LOW);
    }
  }
}

