// ESP32: counting button presses with a hardware interrupt.
// The ISR must be short, so it only touches a volatile variable.

const int BUTTON_PIN = 15;
const int LED_PIN = 2;

volatile unsigned long pressCounter = 0;
volatile unsigned long lastInterruptTime = 0;

void IRAM_ATTR handleButton() {
  unsigned long now = millis();
  // ignore anything within 200 ms, that is just switch bounce
  if (now - lastInterruptTime > 200) {
    pressCounter++;
    lastInterruptTime = now;
  }
}

void setup() {
  Serial.begin(115200);
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(LED_PIN, OUTPUT);

  attachInterrupt(digitalPinToInterrupt(BUTTON_PIN), handleButton, FALLING);
  Serial.println("Interrupt counter ready");
}

void loop() {
  static unsigned long shown = 0;

  if (pressCounter != shown) {
    shown = pressCounter;
    Serial.print("Presses: ");
    Serial.println(shown);

    // blink to confirm
    digitalWrite(LED_PIN, HIGH);
    delay(80);
    digitalWrite(LED_PIN, LOW);
  }
}

