// ESP32 buzzer using the LEDC channel as a square wave generator.
// tone() is not available on every core version, so we drive LEDC directly.

const int BUZZER_PIN = 18;
const int TONE_CHANNEL = 0;
const int TONE_RESOLUTION = 8;

int scale[] = {262, 294, 330, 349, 392, 440, 494, 523};

void playNote(int frequency, int duration) {
  ledcSetup(TONE_CHANNEL, frequency, TONE_RESOLUTION);
  ledcAttachPin(BUZZER_PIN, TONE_CHANNEL);
  ledcWrite(TONE_CHANNEL, 128);   // 50 percent duty = loudest square wave
  delay(duration);
  ledcWrite(TONE_CHANNEL, 0);     // silence
  delay(40);
}

void setup() {
  Serial.begin(115200);
  Serial.println("ESP32 buzzer demo");
}

void loop() {
  for (int i = 0; i < 8; i++) {
    playNote(scale[i], 250);
  }
  delay(1500);
}

