// Morse code SOS on a buzzer and an LED at the same time.

#define BUZZER 6
#define LED 13

const int dotLength = 200;         // one "dot" in milliseconds
const int dashLength = dotLength * 3;
const int toneFreq = 800;

void signal(int lengthMs) {
  tone(BUZZER, toneFreq);
  digitalWrite(LED, HIGH);
  delay(lengthMs);
  noTone(BUZZER);
  digitalWrite(LED, LOW);
  delay(dotLength);   // gap between symbols
}

void setup() {
  pinMode(BUZZER, OUTPUT);
  pinMode(LED, OUTPUT);
}

void loop() {
  // S = three dots
  for (int i = 0; i < 3; i++) {
    signal(dotLength);
  }
  delay(dotLength * 2);

  // O = three dashes
  for (int i = 0; i < 3; i++) {
    signal(dashLength);
  }
  delay(dotLength * 2);

  // S again
  for (int i = 0; i < 3; i++) {
    signal(dotLength);
  }

  delay(3000);   // long pause before repeating
}

