// HC-SR04 ultrasonic sensor: print the distance to the Serial Monitor.
// Sound travels about 0.034 cm per microsecond.

const int trigPin = 9;
const int echoPin = 10;

void setup() {
  Serial.begin(9600);
  pinMode(trigPin, OUTPUT);
  pinMode(echoPin, INPUT);
}

void loop() {
  // send a clean 10 microsecond pulse
  digitalWrite(trigPin, LOW);
  delayMicroseconds(2);
  digitalWrite(trigPin, HIGH);
  delayMicroseconds(10);
  digitalWrite(trigPin, LOW);

  // measure how long the echo pin stays HIGH
  long duration = pulseIn(echoPin, HIGH);

  // divide by two because the sound travels there and back
  float distanceCm = duration * 0.034 / 2;

  Serial.print("Distance: ");
  Serial.print(distanceCm);
  Serial.println(" cm");

  delay(300);
}

