// Turn on a warning LED when something comes closer than 20 cm.

const int TRIG_PIN = 6;
const int ECHO_PIN = 7;
const int WARNING_LED = 5;

const float alertDistance = 20.0;   // cm

float readDistance() {
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);

  long echoTime = pulseIn(ECHO_PIN, HIGH, 30000);   // 30 ms timeout
  return echoTime * 0.034 / 2;
}

void setup() {
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  pinMode(WARNING_LED, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  float distance = readDistance();

  if (distance > 0 && distance < alertDistance) {
    digitalWrite(WARNING_LED, HIGH);
    Serial.println("Object close!");
  } else {
    digitalWrite(WARNING_LED, LOW);
  }

  delay(150);
}

