// Ultrasonic readings jump around a lot, so we average five samples.

const int TRIGGER = 12;
const int ECHO = 11;
const int SAMPLES = 5;

long measureOnce() {
  digitalWrite(TRIGGER, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIGGER, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIGGER, LOW);
  return pulseIn(ECHO, HIGH, 25000);
}

void setup() {
  pinMode(TRIGGER, OUTPUT);
  pinMode(ECHO, INPUT);
  Serial.begin(9600);
  Serial.println("Averaged distance meter");
}

void loop() {
  long total = 0;

  for (int i = 0; i < SAMPLES; i++) {
    total = total + measureOnce();
    delay(30);   // let the echo die away between pings
  }

  long average = total / SAMPLES;
  float cm = average * 0.034 / 2;

  Serial.print("Average distance: ");
  Serial.print(cm, 1);
  Serial.println(" cm");

  delay(500);
}

