// ESP32: parse commands of the form "led 1" or "pwm 128".

const int LED_PIN = 2;
const int PWM_PIN = 4;
const int PWM_CHANNEL = 0;

String inputLine = "";

void setup() {
  Serial.begin(115200);
  pinMode(LED_PIN, OUTPUT);

  ledcSetup(PWM_CHANNEL, 5000, 8);
  ledcAttachPin(PWM_PIN, PWM_CHANNEL);

  Serial.println("Ready. Try: led 1 / led 0 / pwm 128");
}

void loop() {
  while (Serial.available() > 0) {
    char c = Serial.read();

    if (c == '\n') {
      inputLine.trim();
      handleCommand(inputLine);
      inputLine = "";
    } else {
      inputLine += c;
    }
  }
}

void handleCommand(String line) {
  int spaceAt = line.indexOf(' ');

  if (spaceAt < 0) {
    Serial.println("Format: <command> <value>");
    return;
  }

  String name = line.substring(0, spaceAt);
  int value = line.substring(spaceAt + 1).toInt();

  if (name == "led") {
    digitalWrite(LED_PIN, value > 0 ? HIGH : LOW);
    Serial.print("LED set to ");
    Serial.println(value);
  } else if (name == "pwm") {
    value = constrain(value, 0, 255);
    ledcWrite(PWM_CHANNEL, value);
    Serial.print("PWM set to ");
    Serial.println(value);
  } else {
    Serial.print("Unknown command: ");
    Serial.println(name);
  }
}

