// Traffic light built as a state machine with millis().
// Each state knows how long it lasts and what comes next.

const int RED_LED = 2;
const int YELLOW_LED = 3;
const int GREEN_LED = 4;

const int STATE_RED = 0;
const int STATE_RED_YELLOW = 1;
const int STATE_GREEN = 2;
const int STATE_YELLOW = 3;

int currentState = STATE_RED;
unsigned long stateStarted = 0;

void showLights(bool red, bool yellow, bool green) {
  digitalWrite(RED_LED, red);
  digitalWrite(YELLOW_LED, yellow);
  digitalWrite(GREEN_LED, green);
}

void setup() {
  pinMode(RED_LED, OUTPUT);
  pinMode(YELLOW_LED, OUTPUT);
  pinMode(GREEN_LED, OUTPUT);

  stateStarted = millis();
  showLights(true, false, false);
}

void loop() {
  unsigned long elapsed = millis() - stateStarted;

  switch (currentState) {
    case STATE_RED:
      if (elapsed >= 5000) {
        currentState = STATE_RED_YELLOW;
        stateStarted = millis();
        showLights(true, true, false);
      }
      break;

    case STATE_RED_YELLOW:
      if (elapsed >= 1000) {
        currentState = STATE_GREEN;
        stateStarted = millis();
        showLights(false, false, true);
      }
      break;

    case STATE_GREEN:
      if (elapsed >= 5000) {
        currentState = STATE_YELLOW;
        stateStarted = millis();
        showLights(false, true, false);
      }
      break;

    case STATE_YELLOW:
      if (elapsed >= 2000) {
        currentState = STATE_RED;
        stateStarted = millis();
        showLights(true, false, false);
      }
      break;
  }
}

