int measureDistance() {
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);

  long duration = pulseIn(ECHO_PIN, HIGH, 30000);
  if (duration == 0) {
    return 400;    // nothing in range
  }
  return duration * 0.034 / 2;
}

void setup() {
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  pinMode(GREEN_LED, OUTPUT);
  pinMode(YELLOW_LED, OUTPUT);
  pinMode(RED_LED, OUTPUT);
  pinMode(BUZZER, OUTPUT);

  Serial.begin(9600);
  Serial.println("Parking sensor started");
}

void loop() {
  int distance = measureDistance();

  digitalWrite(GREEN_LED, LOW);
  digitalWrite(YELLOW_LED, LOW);
  digitalWrite(RED_LED, LOW);

  int beepInterval;

  if (distance > 60) {
    digitalWrite(GREEN_LED, HIGH);
    beepInterval = 0;               // no beeping, plenty of room
  } else if (distance > 25) {
    digitalWrite(YELLOW_LED, HIGH);
    beepInterval = 500;
  } else if (distance > 10) {
    digitalWrite(RED_LED, HIGH);
    beepInterval = 200;
  } else {
    digitalWrite(RED_LED, HIGH);
    beepInterval = 60;              // almost touching, nearly a solid tone
  }

  if (beepInterval > 0 && millis() - lastBeep >= (unsigned long)beepInterval) {
    lastBeep = millis();
    tone(BUZZER, 2000, 40);
  }

  Serial.print("distance: ");
  Serial.println(distance);

  delay(60);
