  if (currentBrightness < targetBrightness) {
    currentBrightness++;
  } else if (currentBrightness > targetBrightness) {
    currentBrightness--;
  }

  analogWrite(LAMP_PIN, currentBrightness);

  Serial.print("light=");
  Serial.print(light);
  Serial.print("  lamp=");
  Serial.println(currentBrightness);

  delay(20);
}

