// Automatic plant watering.
// Soil sensor + relay driving a small pump, with a safety limit on run time.

const int MOISTURE_PIN = A0;
const int PUMP_RELAY = 5;
const int STATUS_LED = 6;

const int dryLevel = 600;              // higher reading = drier soil
const unsigned long maxPumpTime = 4000;   // never run the pump longer than this
const unsigned long restTime = 30000;     // wait before checking again

void pumpOn() {
  digitalWrite(PUMP_RELAY, LOW);    // active LOW relay board
  digitalWrite(STATUS_LED, HIGH);
}

void pumpOff() {
  digitalWrite(PUMP_RELAY, HIGH);
  digitalWrite(STATUS_LED, LOW);
}

void setup() {
  pinMode(PUMP_RELAY, OUTPUT);
  pinMode(STATUS_LED, OUTPUT);
  pumpOff();

  Serial.begin(9600);
  Serial.println("Plant watering system started");
}

void loop() {
  int moisture = analogRead(MOISTURE_PIN);

  Serial.print("Soil reading: ");
  Serial.println(moisture);

  if (moisture > dryLevel) {
    Serial.println("Soil is dry, watering now");
    pumpOn();
    delay(maxPumpTime);
    pumpOff();

    Serial.println("Waiting for the water to soak in");
    delay(restTime);
  } else {
    Serial.println("Soil is wet enough");
    delay(5000);
  }
}

