  pinMode(gameLed, OUTPUT);
  pinMode(gameButton, INPUT_PULLUP);
  pinMode(beeper, OUTPUT);

  Serial.begin(9600);
  randomSeed(analogRead(A5));   // an unconnected pin gives us noise for the seed

  Serial.println("Reaction game! Press the button when the LED lights up.");
}

void loop() {
  Serial.println("Get ready...");
  digitalWrite(gameLed, LOW);

  // random wait between 2 and 6 seconds
  delay(random(2000, 6000));

  // if the player is cheating and already holding the button, scold them
  if (digitalRead(gameButton) == LOW) {
    Serial.println("Too early! Let go of the button.");
    tone(beeper, 200, 500);
    delay(2000);
    return;
  }

  digitalWrite(gameLed, HIGH);
  lightOnTime = millis();

  // wait for the press
  while (digitalRead(gameButton) == HIGH) {
    // just keep looking
  }

  unsigned long reaction = millis() - lightOnTime;
  digitalWrite(gameLed, LOW);
  tone(beeper, 1200, 120);

  Serial.print("Your time: ");
  Serial.print(reaction);
  Serial.println(" ms");

  if (reaction < bestTime) {
    bestTime = reaction;
    Serial.println("New best score!");
  }

  Serial.print("Best so far: ");
  Serial.print(bestTime);
  Serial.println(" ms");

