// Temperature controlled fan on the ESP32.
// An analog temperature sensor sets the fan speed, with a warning LED when hot.

const int TEMP_SENSOR = 35;
const int FAN_PIN = 19;
const int WARN_LED = 2;

const int FAN_CHANNEL = 0;

const float fanStartTemp = 25.0;   // degrees C where the fan begins
const float fanFullTemp = 35.0;    // degrees C where the fan is flat out
const float warningTemp = 38.0;

void setup() {
  Serial.begin(115200);
  pinMode(WARN_LED, OUTPUT);

  ledcSetup(FAN_CHANNEL, 25000, 8);   // 25 kHz is quiet for a fan
  ledcAttachPin(FAN_PIN, FAN_CHANNEL);

  Serial.println("Fan controller started");
}

float readTemperature() {
  int raw = analogRead(TEMP_SENSOR);
  float millivolts = raw * 3300.0 / 4095.0;
  return millivolts / 10.0;    // 10 mV per degree
}

void loop() {
  float temperature = readTemperature();
  int fanSpeed = 0;

  if (temperature >= fanFullTemp) {
    fanSpeed = 255;
  } else if (temperature > fanStartTemp) {
    fanSpeed = map((int)temperature, (int)fanStartTemp, (int)fanFullTemp, 90, 255);
  }

  ledcWrite(FAN_CHANNEL, fanSpeed);
  digitalWrite(WARN_LED, temperature >= warningTemp ? HIGH : LOW);

  Serial.print("Temp: ");
  Serial.print(temperature, 1);
  Serial.print(" C   Fan: ");
  Serial.println(fanSpeed);

  delay(1000);
}

