// Pedestrian crossing.
// Cars get green until somebody presses the button, then the lights change
// and the buzzer ticks while people cross.

const int carRed = 2;
const int carYellow = 3;
const int carGreen = 4;

const int walkRed = 5;
const int walkGreen = 6;

const int crossButton = 7;
const int crossBuzzer = 8;

void carsGo() {
  digitalWrite(carRed, LOW);
  digitalWrite(carYellow, LOW);
  digitalWrite(carGreen, HIGH);
  digitalWrite(walkRed, HIGH);
  digitalWrite(walkGreen, LOW);
}

void setup() {
  pinMode(carRed, OUTPUT);
  pinMode(carYellow, OUTPUT);
  pinMode(carGreen, OUTPUT);
  pinMode(walkRed, OUTPUT);
  pinMode(walkGreen, OUTPUT);
  pinMode(crossButton, INPUT_PULLUP);
  pinMode(crossBuzzer, OUTPUT);

  carsGo();
  Serial.begin(9600);
  Serial.println("Crossing ready");
}

void loop() {
  if (digitalRead(crossButton) == LOW) {
    Serial.println("Button pressed, stopping the traffic");

    // cars get a warning
    digitalWrite(carGreen, LOW);
    digitalWrite(carYellow, HIGH);
    delay(2000);
    digitalWrite(carYellow, LOW);
    digitalWrite(carRed, HIGH);
    delay(1000);

    // pedestrians walk
    digitalWrite(walkRed, LOW);
    digitalWrite(walkGreen, HIGH);

    for (int i = 0; i < 8; i++) {
      tone(crossBuzzer, 1000, 80);
      delay(800);
    }

    // flashing warning that the time is nearly up
    for (int i = 0; i < 6; i++) {
      digitalWrite(walkGreen, LOW);
      delay(250);
      digitalWrite(walkGreen, HIGH);
      delay(250);
    }

    digitalWrite(walkGreen, LOW);
    digitalWrite(walkRed, HIGH);
    delay(1000);

    // cars can move again
    digitalWrite(carRed, LOW);
    carsGo();
    Serial.println("Traffic moving again");
  }
}
